function validate([img1, img2]) {
  const n = img1.length;
  if (n < 1 || n > 30) return 'n must be between 1 and 30.';
  if (img2.length !== n) return 'Both images must be n x n with the same n.';
  for (const img of [img1, img2]) {
    for (const row of img) {
      if (!Array.isArray(row) || row.length !== n) return 'Each image must be square: every row has n cells.';
      if (row.some(v => v !== 0 && v !== 1)) return 'Every cell is 0 or 1.';
    }
  }
  return null;
}

