function largestOverlap(img1, img2) {
  const n = img1.length;
  let best = 0;

  for (let rowShift = -(n - 1); rowShift < n; rowShift++) {
    for (let colShift = -(n - 1); colShift < n; colShift++) {
      let count = 0;
      for (let r = 0; r < n; r++) {
        const r2 = r + rowShift;
        if (r2 < 0 || r2 >= n) {
          continue;
        }
        for (let c = 0; c < n; c++) {
          const c2 = c + colShift;
          if (c2 >= 0 && c2 < n && img1[r][c] === 1 && img2[r2][c2] === 1) {
            count++;
          }
        }
      }
      best = Math.max(best, count);
    }
  }
  return best;
}

