function largestOverlap(img1, img2) {
  // Count, for every pair of 1-cells, the vector that moves the first onto the second.
  const n = img1.length;
  const ones1 = [], ones2 = [];
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
    if (img1[i][j]) ones1.push([i, j]);
    if (img2[i][j]) ones2.push([i, j]);
  }
  const tally = new Map();
  let most = 0;
  for (const [a, b] of ones1) for (const [x, y] of ones2) {
    const key = (x - a) + ',' + (y - b);
    const v = (tally.get(key) || 0) + 1;
    tally.set(key, v);
    if (v > most) most = v;
  }
  return most;
}

