function generate(rand, size) {
  const n = size === 'large' ? 25 + Math.floor(rand() * 6) : 1 + Math.floor(rand() * 5);
  const grid = (density) => Array.from({ length: n }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
  const d1 = rand(), d2 = rand();
  return [grid(d1), grid(d2)];
}
